items.body:
[PRODUCE] STEP 1 — Open main.tf. Replace the entire file with this:

      terraform {
        required_providers { aws = { source = "hashicorp/aws", version = "~> 5.0" } }
      }
      provider "aws" { region = "us-east-1" }

      resource "aws_s3_bucket" "portfolio" {
        bucket = "YOUR-NAME-edge-portfolio-2026"
      }

      resource "aws_cloudfront_origin_access_identity" "oai" {
        comment = "OAI for edge-portfolio"
      }

      data "aws_iam_policy_document" "s3_policy" {
        statement {
          actions   = ["s3:GetObject"]
          resources = ["${aws_s3_bucket.portfolio.arn}/*"]
          principals {
            type        = "AWS"
            identifiers = [aws_cloudfront_origin_access_identity.oai.iam_arn]
          }
        }
      }

      resource "aws_s3_bucket_policy" "portfolio" {
        bucket = aws_s3_bucket.portfolio.id
        policy = data.aws_iam_policy_document.s3_policy.json
      }

      resource "aws_cloudfront_distribution" "portfolio" {
        enabled             = true
        default_root_object = "index.html"
        origin {
          domain_name = aws_s3_bucket.portfolio.bucket_regional_domain_name
          origin_id   = "s3-portfolio"
          s3_origin_config {
            origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
          }
        }
        default_cache_behavior {
          target_origin_id       = "s3-portfolio"
          viewer_protocol_policy = "redirect-to-https"
          allowed_methods        = ["GET", "HEAD"]
          cached_methods         = ["GET", "HEAD"]
          forwarded_values { query_string = false; cookies { forward = "none" } }
        }
        restrictions { geo_restriction { restriction_type = "none" } }
        viewer_certificate { cloudfront_default_certificate = true }
      }

      output "cloudfront_url" {
        value = "https://${aws_cloudfront_distribution.portfolio.domain_name}"
      }

  Replace YOUR-NAME with your name (same as before).

STEP 2 — Apply.
      terraform apply
  Type 'yes'. CloudFront takes 5-10 minutes to deploy globally.
  YOU SHOULD SEE at the end: cloudfront_url = "https://xxxxxxxx.cloudfront.net"

STEP 3 — Upload index.html.
      aws s3 cp ../index.html s3://YOUR-NAME-edge-portfolio-2026/
  YOU SHOULD SEE: 'upload: ../index.html to s3://...'

STEP 4 — Visit your CloudFront URL.
  Wait 5 minutes for CloudFront to fully deploy. Then open the URL.
  YOU SHOULD SEE: your portfolio page, served over HTTPS, from a global CDN.

